func emptyUnit(pkg string, bases ...string) *ir.Unit {
	u := &ir.Unit{Package: pkg, ProtocolId: 0x0123456789abcdef}
	for _, b := range bases {
		u.Files = append(u.Files, &ir.File{Base: b})
	}
	return u
}

// writeTree writes the generated files under dir.
func writeTree(t *testing.T, dir string, files map[string][]byte) {
	t.Helper()
	for rel, data := range files {
		p := filepath.Join(dir, filepath.FromSlash(rel))
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(p, data, 0o644); err != nil {
			t.Fatal(err)
		}
	}
}

// TestPythonEmptyUnitGenerates: a unit that declares nothing generates its
// package, one module per file, and the runtime beside them, and the same
// unit generates the same bytes every time (SPEC §6.1).
func TestPythonEmptyUnitGenerates(t *testing.T) {
	t.Parallel()
	u := emptyUnit("hello", "Wire", "Hello")
	files, err := Generate(u)
	if err != nil {
		t.Fatal(err)
	}
	runtime, err := Runtime()
	if err != nil {
		t.Fatal(err)
	}
	want := []string{"hello/Hello.py", "hello/Wire.py", "hello/__init__.py", "hello/py.typed"}
	for rel := range runtime {
		want = append(want, "hello/"+rel)
	}
	sort.Strings(want)
	if got := slices.Sorted(maps.Keys(files)); !slices.Equal(got, want) {
		t.Fatalf("emitted %v\nwant    %v", got, want)
	}
	for _, rel := range []string{"_schema/__init__.py", "_schema/serialize/__init__.py", "_schema/serialize/_core.py"} {
		if _, ok := runtime[rel]; !ok {
			t.Errorf("the runtime has no %s", rel)
		}
	}
	init := string(files["hello/__init__.py"])
	for _, line := range []string{
		"# Code generated by the schema compiler from the unit hello. DO NOT EDIT.",
		"from ._schema import InvalidValue, Refused",
		"from . import Hello",
		"from . import Wire",
		"PROTOCOL_ID: Final = 0x0123456789abcdef",
	} {
		if !strings.Contains(init, line+"\n") {
			t.Errorf("hello/__init__.py lacks the line %q:\n%s", line, init)
		}
	}
	again, err := Generate(emptyUnit("hello", "Hello", "Wire"))
	if err != nil {
		t.Fatal(err)
	}
	for rel, data := range files {
		if !bytes.Equal(again[rel], data) {
			t.Errorf("%s differs between two generations of the same unit", rel)
		}
	}
}

const importProbe = pyrun.ImportPrelude + `import json
import hello
from hello import InvalidValue, Refused, PROTOCOL_ID
from hello._schema import serialize

print("%016x" % PROTOCOL_ID)
print(issubclass(Refused, ValueError), issubclass(InvalidValue, ValueError))
r = Refused("past_end", "a short read")
print(r.reason, str(r))
v = InvalidValue("Player.name", "a lone surrogate")
print(v.path, v.rule)
print(hello.json.__name__, json.dumps([1]))
print(serialize.FORMAT_VERSION)
`

// TestPythonEmptyUnitImportsUnderBothPins: the generated package imports
// under both pinned interpreters, isolated, from the directory the probe
// names and nothing else; its errors are ValueErrors carrying their fields;
// a module named like a standard library module (json) lives inside the
// package and shadows nothing; and the vendored serialize.py loads as the
// runtime's subpackage.
func TestPythonEmptyUnitImportsUnderBothPins(t *testing.T) {
	t.Parallel()
	files, err := Generate(emptyUnit("hello", "Hello", "json"))
	if err != nil {
		t.Fatal(err)
	}
	want := strings.Join([]string{
		"0123456789abcdef",
		"True True",
		"past_end past_end: a short read",
		"Player.name a lone surrogate",
		"hello.json [1]",
		"2.0",
	}, "\n") + "\n"
	for _, run := range []struct {
		name string
		fn   func(testing.TB, string, string, map[string][]byte) []byte
	}{{"current", pyrun.Run}, {"floor", pyrun.RunFloor}} {
		t.Run(run.name, func(t *testing.T) {
			t.Parallel()
			dir := t.TempDir()
			writeTree(t, dir, files)
			got := string(run.fn(t, dir, "main.py", map[string][]byte{"main.py": []byte(importProbe)}))
			if got != want {
				t.Fatalf("probe printed\n%s\nwant\n%s", got, want)
			}
		})
	}
}

// TestPythonGeneratedPackageIsStrictClean: mypy in strict mode, at the
// floor's language version, finds nothing in the generated package, the
// runtime and serialize.py included. Its control is
// TestPythonStrictGateGoesRed.
func TestPythonGeneratedPackageIsStrictClean(t *testing.T) {
	t.Parallel()
	files, err := Generate(emptyUnit("hello", "Hello", "Wire"))
	if err != nil {
		t.Fatal(err)
	}
	dir := t.TempDir()
	writeTree(t, dir, files)
	out, err := pyrun.Analyze(t, dir, "hello")
	if err != nil || !strings.Contains(out, "Success: no issues found") {
		t.Fatalf("mypy --strict over the generated package: %v\n%s", err, out)
	}
}

// TestPythonStrictGateGoesRed is the strict gate's negative control: the same
// package with one ill-typed line planted in a generated module must go red,
// naming that module.
func TestPythonStrictGateGoesRed(t *testing.T) {
	t.Parallel()
	files, err := Generate(emptyUnit("hello", "Hello", "Wire"))
	if err != nil {
		t.Fatal(err)
	}
	files["hello/Hello.py"] = append(files["hello/Hello.py"], []byte("planted: int = \"text\"\n")...)
	dir := t.TempDir()
	writeTree(t, dir, files)
	out, err := pyrun.Analyze(t, dir, "hello")
	if err == nil {
		t.Fatalf("mypy --strict passed a module with a planted type error:\n%s", out)
	}
	if !strings.Contains(out, filepath.Join("hello", "Hello.py")) || !strings.Contains(out, "Incompatible types in assignment") {
		t.Fatalf("mypy went red, but not on the planted line:\n%s", out)
	}
}

// TestPythonRefusesUncarriedKindsByName: the packet core carries the class
// surface of every declaration and the wire of the kinds it names; a field or
// item of any other kind is refused at generate time by its kind, naming P4.
func TestPythonRefusesUncarriedKindsByName(t *testing.T) {
	t.Parallel()
	generates := []struct {
		name string
		decl ir.Decl
	}{
		{"const", &ir.Const{Name: "MaxPlayers", Int: big.NewInt(64)}},
		{"enum", &ir.Enum{Name: "Weapon", Variants: []string{"Laser"}, Max: 1}},
		{"flags", &ir.Flags{Name: "Caps", Variants: []string{"Armed"}, WireBits: 1}},
		{"type", &ir.Struct{Name: "Player", Fields: []*ir.Field{
			{Name: "health", Type: ir.FieldType{Kind: ir.TInt, Width: 16, Signed: true}},
			{Name: "alive", Type: ir.FieldType{Kind: ir.TBool}},
		}}},
		{"union", &ir.Union{Name: "Event"}},
	}
	for _, c := range generates {
		u := emptyUnit("game", "Game")
		u.Files[0].Decls = []ir.Decl{c.decl}
		if _, err := Generate(u); err != nil {
			t.Errorf("%s: a carried declaration was refused: %v", c.name, err)
		}
	}
	refused := []struct {
		name string
		decl ir.Decl
		want string
	}{
		{"bits", &ir.Struct{Name: "Probe", Fields: []*ir.Field{{Name: "small", Type: ir.FieldType{Kind: ir.TBits, Width: 9}}}}, "uses bits"},
		{"fixed", &ir.Struct{Name: "Probe", Fields: []*ir.Field{{Name: "x", Type: ir.FieldType{Kind: ir.TFixed, Width: 32, IntBits: 16, FracBits: 16}}}}, "uses fixed"},
		{"float32", &ir.Struct{Name: "Probe", Fields: []*ir.Field{{Name: "x", Type: ir.FieldType{Kind: ir.TFloat32}}}}, "uses float32"},
		{"float64", &ir.Struct{Name: "Probe", Fields: []*ir.Field{{Name: "x", Type: ir.FieldType{Kind: ir.TFloat64}}}}, "uses float64"},
		{"string", &ir.Struct{Name: "Probe", Fields: []*ir.Field{{Name: "x", Type: ir.FieldType{Kind: ir.TString, Size: 8}}}}, "uses string"},
		{"bytes", &ir.Struct{Name: "Probe", Fields: []*ir.Field{{Name: "x", Type: ir.FieldType{Kind: ir.TBytes, Size: 8}}}}, "uses bytes"},
		{"int128", &ir.Struct{Name: "Probe", Fields: []*ir.Field{{Name: "x", Type: ir.FieldType{Kind: ir.TInt, Width: 128}}}}, "uses int128"},
		{"array", &ir.Struct{Name: "Probe", Fields: []*ir.Field{{Name: "x", Array: ir.ArrayFixed, ArrayBound: 2, Type: ir.FieldType{Kind: ir.TInt, Width: 8}}}}, "uses array"},
		{"const item", &ir.Struct{Name: "Probe", Items: []ir.Item{&ir.ConstItem{Value: big.NewInt(1), Bits: 8}}}, "uses const"},
		{"reserved item", &ir.Struct{Name: "Probe", Items: []ir.Item{&ir.ReservedItem{Bits: 5}}}, "uses reserved"},
		{"align item", &ir.Struct{Name: "Probe", Items: []ir.Item{&ir.AlignItem{}}}, "uses align"},
	}
	for _, c := range refused {
		u := emptyUnit("game", "Game")
		u.Files[0].Decls = []ir.Decl{c.decl}
		files, err := Generate(u)
		if err == nil || !strings.Contains(err.Error(), c.want) {
			t.Errorf("%s: got %v (%d files), want a refusal containing %q", c.name, err, len(files), c.want)
		}
	}
	u := emptyUnit("game", "Game")
	u.Files[0].Tables = []*ir.Struct{{Name: "Fleet", IsTable: true}}
	if _, err := Generate(u); err == nil || !strings.Contains(err.Error(), "declares table Fleet, and the Python target does not carry tables yet") {
		t.Errorf("a table: got %v", err)
	}
}

// TestPythonIdentifierRules holds docs/PORT-PYTHON.md, IDENTIFIERS: each rule
// refuses its case by name, and each legal neighbor generates.
func TestPythonIdentifierRules(t *testing.T) {
	t.Parallel()
	withDecl := func(d ir.Decl) *ir.Unit {
		u := emptyUnit("game", "Game")
		u.Files[0].Decls = []ir.Decl{d}
		return u
	}
	refused := []struct {
		name string
		unit *ir.Unit
		want string
	}{
		{"package keyword", emptyUnit("lambda", "Game"), "the package lambda is a Python keyword"},
		{"package stdlib (3.11 and 3.15)", emptyUnit("json", "Game"), "the package json is a standard library module"},
		{"package stdlib (3.11 only)", emptyUnit("telnetlib", "Game"), "the package telnetlib is a standard library module"},
		{"package not an identifier", emptyUnit("my-game", "Game"), `the package "my-game" is not a Python identifier`},
		{"package dunder", emptyUnit("__game", "Game"), "the package __game starts with"},
		{"module not an identifier", emptyUnit("game", "my-file"), "my-file is not a Python identifier"},
		{"module keyword", emptyUnit("game", "class"), "class is a Python keyword"},
		{"module runtime", emptyUnit("game", "_schema"), "a name the generated package reserves"},
		{"module init", emptyUnit("game", "__init__"), "a name the generated package reserves"},
		{"module case fold", emptyUnit("game", "Wire", "wire"), "differ only in case"},
		{"declaration keyword None", withDecl(&ir.Struct{Name: "None"}), "type None is a Python keyword"},
		{"field keyword None", withDecl(&ir.Struct{Name: "Player", Fields: []*ir.Field{{Name: "None"}}}), "Player's field None is a Python keyword"},
		{"field keyword global", withDecl(&ir.Struct{Name: "Pack", Fields: []*ir.Field{{Name: "global"}}}), "Pack's field global is a Python keyword"},
		{"declaration dunder", withDecl(&ir.Struct{Name: "__Player"}), "type __Player starts with __"},
		{"declaration helper prefix", withDecl(&ir.Enum{Name: "_s_Weapon"}), "enum _s_Weapon starts with _s_"},
		{"declaration builtin", withDecl(&ir.Struct{Name: "Exception"}), "type Exception is a Python builtin"},
		{"declaration builtin (3.15 only)", withDecl(&ir.Const{Name: "PythonFinalizationError"}), "const PythonFinalizationError is a Python builtin"},
		{"field dunder", withDecl(&ir.Struct{Name: "Player", Fields: []*ir.Field{{Name: "__secret"}}}), "Player's field __secret starts with __"},
		{"field generated member", withDecl(&ir.Struct{Name: "Player", Fields: []*ir.Field{{Name: "save"}}}), "Player's field save is the name of a member the generated class defines"},
		{"variant helper prefix", withDecl(&ir.Enum{Name: "Weapon", Variants: []string{"_s_Laser"}}), "Weapon's variant _s_Laser starts with _s_"},
		{"arm generated member", withDecl(&ir.Union{Name: "Event", Variants: []ir.UnionVariant{{Name: "load"}}}), "union Event's arm load is the name of a member"},
	}
	for _, c := range refused {
		err := CheckNames(c.unit)
		if err == nil || !strings.Contains(err.Error(), c.want) {
			t.Errorf("%s: got %v, want a refusal containing %q", c.name, err, c.want)
		}
		if _, gerr := Generate(c.unit); gerr == nil {
			t.Errorf("%s: Generate emitted a unit CheckNames refuses", c.name)
		}
	}
	legal := []struct {
		name string
		unit *ir.Unit
	}{
		{"module named like the standard library", emptyUnit("game", "json", "types")},
		{"package named like a soft keyword", emptyUnit("match", "Game")},
		{"field named like a builtin", withDecl(&ir.Struct{Name: "Player", Fields: []*ir.Field{{Name: "list"}, {Name: "range"}}})},
		{"declaration with a single leading underscore", withDecl(&ir.Struct{Name: "_Player"})},
	}
	for _, c := range legal {
		if err := CheckNames(c.unit); err != nil {
			t.Errorf("%s: refused: %v", c.name, err)
		}
	}
}

const namesProbe = `import builtins, keyword, sys
print(" ".join(sorted(sys.stdlib_module_names)))
print(" ".join(sorted(n for n in dir(builtins) if not n.startswith("__"))))
print(" ".join(keyword.kwlist))
`

// TestPythonNameListsAreThePins re-derives the name lists from both pinned
// interpreters: the standard library modules and the builtins are the union
// of the two, and the hard keywords are each interpreter's keyword.kwlist.
func TestPythonNameListsAreThePins(t *testing.T) {
	t.Parallel()
	stdlib, builtins := map[string]bool{}, map[string]bool{}
	for _, run := range []func(testing.TB, string, string, map[string][]byte) []byte{pyrun.Run, pyrun.RunFloor} {
		dir := t.TempDir()
		lines := strings.Split(strings.TrimRight(string(run(t, dir, "main.py", map[string][]byte{"main.py": []byte(namesProbe)})), "\n"), "\n")
		if len(lines) != 3 {
			t.Fatalf("names probe printed %d lines, want 3", len(lines))
		}
		for w := range strings.FieldsSeq(lines[0]) {
			stdlib[w] = true
		}
		for w := range strings.FieldsSeq(lines[1]) {
			builtins[w] = true
		}
		if kw := wordSet(lines[2]); !maps.Equal(kw, pythonKeywords) {
			t.Errorf("pythonKeywords is not keyword.kwlist of a pin:\npin  %v\nlist %v", slices.Sorted(maps.Keys(kw)), slices.Sorted(maps.Keys(pythonKeywords)))
		}
	}
	for name, got := range map[string][2]map[string]bool{
		"pythonStdlibModules": {stdlib, pythonStdlibModules},
		"pythonBuiltins":      {builtins, pythonBuiltins},
	} {
		pins, list := got[0], got[1]
		for w := range pins {
			if !list[w] {
				t.Errorf("%s lacks %s, which a pin has", name, w)
			}
		}
		for w := range list {
			if !pins[w] {
				t.Errorf("%s has %s, which neither pin has", name, w)
			}
		}
	}
}
